function tutorialForKey(key){if(tutorialCatalog[key])return tutorialCatalog[key];const m=prototypeGames[key];if(!m)return null;if(key==='mystery')return {name:m.name,icon:m.icon,steps:[{title:'Move by board destinations',body:'Family Mystery is intended as a dimensional board game. Select a legal destination rather than free-walking.'},{title:'Make suggestions',body:'Use clues, rooms and suspects through the existing mystery rules.'},{title:'Solve the mystery',body:'An accusation ends the case only when the underlying rules say it does.'}]};if(key==='prophunt')return {name:m.name,icon:m.icon,steps:[{title:'Hide or hunt',body:'Choose your role and learn the map controls.'},{title:'Use role abilities',body:'Hiders disguise and use decoys; hunters search and shoot with the role-specific controls.'},{title:'Reset the view',body:'Camera zoom and Reset View remain available when scenery blocks the shot.'}]};if(key==='birthday')return {name:m.name,icon:m.icon,steps:[{title:'Read the course ahead',body:'Run and jump through checkpoints toward the birthday seat.'},{title:'Use the camera for the next obstacle',body:'Orbit, zoom and Reset View help frame the route.'},{title:'Finish the race',body:'Reach the final birthday area to complete the course.'}]};return {name:m.name,icon:m.icon,steps:[{title:'Explore the island',body:'Move around the island and interact with homes, work and family activities.'},{title:'Use nearby interactions',body:'The interface surfaces actions only when they are available.'},{title:'Build your island life',body:'Work, earn, shop, craft and decorate in the persistent world.'}]}}
