 if(d==='drawPile')return `<div class="tutorial-tabletop"><button class="tutorial-draw-stack hinted" data-tutorial-action="correct"><span>🌲</span><b>DRAW HERE</b></button><div class="tutorial-discard">8♥</div></div>`;
 if(d==='thirtyOneSwap')return `<div class="tutorial-hand"><button>4♣</button><button class="hinted" data-tutorial-action="correct">9♥</button><button>K♥</button></div>`;
 if(d==='euchreTrump')return `<div class="tutorial-bids"><button data-tutorial-action="wrong">♣ Clubs</button><button class="hinted" data-tutorial-action="correct">♥ Hearts</button><button data-tutorial-action="wrong">♠ Spades</button></div>`;
 if(d==='euchreTrick')return `<div class="tutorial-trick-seats"><span><b>John</b><i>10♥</i></span><span><b>Kristen</b><i>Q♥</i></span><span><b>You</b><button class="hinted" data-tutorial-action="correct">A♥</button></span><span><b>Holly</b><i>?</i></span></div>`;
 if(d==='cribSorted')return `<div class="tutorial-hand crib-tutorial-hand">${['A♣','2♥','5♠','8♦','10♣','K♥'].map(c=>`<button disabled>${c}</button>`).join('')}</div>`;
