function blackPointHTML(s,e,n,top,map){const ids=[...s.players].sort((a,b)=>a.seat-b.seat).map(p=>p.id),acts=map.get(String(n))||[],selected=String(session.selectedBgFrom)===String(n),destActs=selected?acts:[],present=ids.filter(id=>(e.points?.[id]?.[n]||0)>0),topId=e.top?.[n],ordered=present.length<2?present:[...present.filter(id=>id!==topId),topId].filter(Boolean);const layers=ordered.map((id,i)=>blackStackLayer(s,e,n,id,acts,i===ordered.length-1?'top-stack':'bottom-stack')).join('');return `<div class="bg-point black-point ${top?'top':'bottom'} ${n%2?'dark':'light'}" data-point="${n}"><span>${n+1}</span>${layers||'<span class="bg-empty-hole"></span>'}${destActs.length?`<div class="bg-dest-actions black-dest-actions">${destActs.map(([a,i])=>`<button class="${a.args.rescue?'rescue':a.args.direction==='backward'?'backward':'forward'}" data-extra-action="${i}">${a.args.to==='off'?'OFF':Number(a.args.to)+1}<small>${a.args.count>1?`${a.args.count}×`:''}${a.args.value} · ${a.args.direction==='backward'?'BACK':'FWD'}${a.args.rescue?' · SAVE':''}</small></button>`).join('')}</div>`:''}</div>`}
function blackBar(s,e,map){const ids=[...s.players].sort((a,b)=>a.seat-b.seat).map(p=>p.id),acts=map.get('bar')||[];return `<div class="bg-bar black-bar"><small>BAR</small><div class="black-bar-stacks">${ids.map(id=>{const p=s.players.find(x=>x.id===id),count=e.bar?.[id]||0;if(!count)return'';const mine=id===s.viewerId;return `<button class="bg-checker-stack bar black-checker-stack ${mine&&acts.length?'legal':''}" style="--pc:${p.color}" ${mine?`data-bg-from="bar"`:''} ${mine&&!acts.length?`data-black-illegal="${esc(e.illegalHint||'No legal bar entry with these dice.')}"`:''} ${!mine?'disabled':''}><i></i><i></i><i></i>${count>3?`<b>${count}</b>`:''}</button>`}).join('')}</div><b>${ids.map(id=>`${esc(s.players.find(p=>p.id===id)?.name||'Player')}: ${e.bar?.[id]||0}`).join(' · ')}</b></div>`}
