function extraCardLabel(c){if(!c)return'Hidden';if(c.a!=null&&c.b!=null)return `${c.a}-${c.b}`;if(c.wild&&c.rank==='WILD')return'WILD';if(c.kind){if(c.kind==='number')return `${c.rank} · ${String(c.color||'').toUpperCase()}`;return `${c.rank||c.kind}`;}if(c.joker||c.suit==='joker')return'JOKER';return `${c.rank||''}${suitSymbol[c.suit]||''}`}
function extraCardHTML(c,small=false){if(!c)return `<div class="card card-back ${small?'small-card':''}"><div class="big">🌲</div></div>`;if(c.a!=null&&c.b!=null)return dominoHTML(c,small);if(c.wild&&c.rank==='WILD'||typeof c.rank==='number')return skipBoCardHTML(c,small);if(c.kind){const map={fire:'#9e3f30',forest:'#2f6b4f',river:'#397ea5',lantern:'#c49334',wild:'#4c3c5f'},col=map[c.color]||map.wild;return `<div class="card camp-card ${small?'small-card':''}" style="--camp:${col}"><div>${esc(c.rank||c.kind)}</div><div class="big">${c.color==='fire'?'🔥':c.color==='forest'?'🌲':c.color==='river'?'💧':c.color==='lantern'?'🏮':'✦'}</div><div>${esc(String(c.color||'WILD').toUpperCase())}</div></div>`}if(c.joker||c.suit==='joker')return `<div class="card joker-card low ${small?'small-card':''}"><div>JOKER</div><div class="joker-star">★</div><div>${c.jokerIndex?`#${c.jokerIndex}`:''}</div></div>`;return cardHTML(c).replace('class="card ',`class="card ${small?'small-card ':''}`)}
function extraPlayerStat(s,e,p){const id=p.id,t=s.gameType;if(t===GAME.THIRTY_ONE)return `Lives ${p.score}${p.eliminated?' · OUT':''}`;if(t===GAME.CRAZY_EIGHTS)return `Level ${e.levels?.[id]??p.score}`;if(t===GAME.GOLF)return `Total ${p.score}`;if(t===GAME.POKER)return `Chips ${p.score}${p.eliminated?' · OUT':''}`;if(t===GAME.LAST_HAVEN)return `${e.points?.[id]??0}/15 SP · ${e.resourceCounts?.[id]??0} supplies`;if(t===GAME.EUCHRE){const tm=(p.seat%2===0?'A':'B');return `Team ${tm==='A'?1:2}: ${e.teamScores?.[tm]??0}`;}if(t===GAME.MITTS){const keys=Object.keys(e.teamScores||{}),k=keys.find(x=>String(x)===String(id))??(p.seat%2===0?'A':'B');return `Score ${p.score}`;}if(t===GAME.CRIBBAGE)return `${p.score}/121`;if(t===GAME.PRAIRIE)return `${p.score} chips`;if(t===GAME.BURN_LOGS)return `${e.completed?.[id]??0}/${e.target||7} logs`;if(t===GAME.DECK_SWEEP)return `${p.score} pts`;if(t===GAME.PRESIDENT)return `${p.score} rank pts`;if(t===GAME.CAMPFIRE)return e.mode==='full'?`${p.score} pts`:`${p.handCount} cards`;if(t===GAME.TRAIL){const q=e.pawns?.[id]||[],home=q.filter(x=>x.zone==='home').length;return `${home}/4 home`;}if(t===GAME.MARBLES){const q=e.pawns?.[id]||[],home=q.filter(x=>x.zone==='home').length;return `${home}/5 home`;}if(t===GAME.MEXICAN_TRAIN)return `${e.handCounts?.[id]??p.handCount} tiles · ${e.trains?.[id]?.open?'OPEN':'private'} · ${p.score} pts`;if(t===GAME.SKIP_BO)return `Stock ${e.stocks?.[id]?.count??0} · Hand ${e.handCounts?.[id]??p.handCount}`;if(t===GAME.BACKGAMMON)return `${e.off?.[id]??0}/15 off · Bar ${e.bar?.[id]??0}`;if(t===GAME.BLACK_GAMMON)return `${e.off?.[id]??0}/15 off · Bar ${e.bar?.[id]??0}`;return `Score ${p.score}`}
function crazyProgressPanel(s,e){if(s.gameType!==GAME.CRAZY_EIGHTS)return'';return `<div class="panel crazy-progress-panel"><div class="spread"><strong>Countdown</strong><span class="small muted">8 → A</span></div><div class="crazy-progress-list">${[...s.players].sort((a,b)=>a.seat-b.seat).map(p=>{const level=Number(e.levels?.[p.id]??p.score??8),current=level===1?'A':String(level),previous=level<8?(level+1===1?'A':String(level+1)):null;return `<div style="--pc:${p.color}">${avatarHTML(p,'mini-avatar')}<span><b>${esc(p.name)}</b><small>${previous?`<s>${esc(previous)}</s> → `:''}<strong>${esc(current)}</strong></small></span></div>`}).join('')}</div></div>`}
