function extraHandPanel(s,e){let hand=Array.isArray(e.hand)?sortedCards(e.hand,e.type):[];if(e.type===GAME.CRIBBAGE&&e.phase==='counting'&&Array.isArray(e.countHand)&&e.countHand.length)hand=sortedCards(e.countHand,e.type);if(!hand.length)return'';const active=extraTurnId(e)===s.viewerId||(e.actions||[]).length>0;if(e.type===GAME.CRIBBAGE&&e.phase==='discardCrib'){const need=e.discardNeed||2,sel=session.selectedCribCards||[],dealer=s.players.find(p=>p.id===e.dealerId);return `<div class="extra-hand auto-fit-hand crib-hand"><div class="small extra-hand-label your-turn">YOUR HAND · CHOOSE ${need} FOR ${esc(dealer?.name||'DEALER')}'S CRIB</div><div class="crib-auto-note">Select ${need===2?'two cards':'one card'} · sends automatically</div><div class="extra-card-row" style="--hand-count:${hand.length}">${hand.map(c=>`<button class="extra-hand-card crib-select ${sel.includes(c.id)?'selected':''}" data-crib-card="${c.id}">${extraCardHTML(c,true)}</button>`).join('')}</div></div>`}if(e.type===GAME.CRIBBAGE&&e.phase==='counting'){return `<div class="extra-hand auto-fit-hand crib-count-hand"><div class="small extra-hand-label">YOUR COUNTING HAND</div><div class="extra-card-row">${hand.map(c=>`<span class="extra-hand-card">${extraCardHTML(c,true)}</span>`).join('')}</div></div>`}const goIdx=e.type===GAME.CRIBBAGE&&e.phase==='pegging'?actionIndex(e,'cribGo'):-1;const specialClass=e.type===GAME.MEXICAN_TRAIN?'domino-rack':e.type===GAME.SKIP_BO?'skipbo-hand':'';const noun=e.type===GAME.MEXICAN_TRAIN?'DOMINO RACK':e.type===GAME.SKIP_BO?'FIVE-CARD HAND':'YOUR HAND';return `<div class="extra-hand auto-fit-hand ${e.type===GAME.MARBLES?'marbles-five-hand':''} ${specialClass}">${goIdx>=0?`<button class="crib-go-context" data-extra-action="${goIdx}">GO</button>`:''}<div class="small extra-hand-label ${active?'your-turn':''}">${active?'YOUR TURN · ':''}${noun} · ${hand.length} · TAP A HIGHLIGHTED ${e.type===GAME.MEXICAN_TRAIN?'DOMINO':'CARD'} TO PLAY</div><div class="extra-card-row" style="--hand-count:${hand.length}">${hand.map(c=>{const hits=extraCardActionIndexes(e,c),direct=hits.length===1?hits[0][1]:null,selected=session.selectedExtraCard===c.id;return `<button class="extra-hand-card ${hits.length?'playable':''} ${selected?'selected':''}" ${direct!=null?`data-extra-action="${direct}"`:`data-extra-card="${c.id}"`} ${!hits.length?'disabled':''} title="${hits.length?hits.length===1?'Tap to play':'Tap for play choices':'Not playable right now'}">${extraCardHTML(c,true)}</button>`}).join('')}</div></div>`}
function actionIndex(e,action,pred=()=>true){return (e.actions||[]).findIndex(a=>a.action===action&&pred(a))}
function genericDrawDeck(e,label='DRAW'){const indexed=(e.actions||[]).map((a,i)=>[a,i]).filter(([a])=>!actionCardIds(a).length&&/draw/i.test(a.label||a.action||''));if(!indexed.length)return'';const preferred=indexed.find(([a])=>a.args?.source==='stock'||/deck|unknown|draw 1|draw a card/i.test(a.label||''))||indexed[0];const [a,i]=preferred;return `<button class="table-deck-button draw-required" data-extra-action="${i}" title="${esc(a.label)}"><span class="physical-deck"><i></i><i></i><i></i><b>🌲</b></span><strong>DRAW HERE</strong><small>${esc(a.label)}</small></button>`}
function cribTrackRows(p,e){const score=Math.max(0,Math.min(121,Number(p.score)||0)),previous=Math.max(0,Math.min(121,Number(e.previousScores?.[p.id]??score)||0)),last=e.lastPegEvent?.playerId===p.id?e.lastPegEvent:null;let n=1,rows=[];for(let r=0;r<4;r++){const vals=[];for(let c=0;c<30;c++,n++){const current=n===score,trail=n===previous&&previous!==score,moved=current&&last&&Number(last.to)===score;vals.push(`<i class="crib-hole ${current?'current-peg':''} ${trail?'previous-peg':''} ${moved?'peg-moved':''}" style="--pc:${p.color}" title="${esc(p.name)} · ${n}">${trail?'<b class="crib-peg trail"></b>':''}${current?'<b class="crib-peg current"></b>':''}</i>`)}if(r%2)vals.reverse();rows.push(`<div class="crib-hole-row">${vals.join('')}</div>`)}return`<div class="crib-player-track" style="--pc:${p.color}"><div class="crib-track-name">${avatarHTML(p,'mini-avatar')}<span>${esc(p.name)}</span><strong>${score}/121</strong></div><div class="crib-start-slot">${score===0?'<b class="crib-peg current"></b>':''}${previous===0&&previous!==score?'<b class="crib-peg trail"></b>':''}<small>START</small></div>${rows.join('')}<div class="crib-finish ${score>=121?'current-peg':''} ${previous>=121&&previous!==score?'previous-peg':''}">121${score>=121?'<b class="crib-peg current"></b>':''}${previous>=121&&previous!==score?'<b class="crib-peg trail"></b>':''}</div></div>`}
