function runMarbleMoveAnimation(){const m=session.lastMarbleAnimation,s=session.state,e=s?.game?.extra;if(!m||s?.gameType!==GAME.MARBLES||Date.now()-m.at>2200)return;const el=document.querySelector(`[data-marble-id="${CSS.escape(m.id)}"]`),board=document.querySelector('.marbles-board');if(!el||!board)return;const arr=e.pawns?.[m.playerId]||[],idx=Math.max(0,arr.findIndex(q=>q.id===m.id)),path=marbleAnimationPath(s,e,m.playerId,m.from,m.to,idx),dest=path.at(-1);if(!dest||path.length<2)return;const rect=board.getBoundingClientRect(),px=p=>({x:(p.x-dest.x)/100*rect.width,y:(p.y-dest.y)/100*rect.height});let dist=0;for(let i=1;i<path.length;i++)dist+=Math.hypot(path[i].x-path[i-1].x,path[i].y-path[i-1].y);let acc=0;const frames=[];for(let i=0;i<path.length;i++){if(i){acc+=Math.hypot(path[i].x-path[i-1].x,path[i].y-path[i-1].y)}const t=dist?acc/dist:i/(path.length-1),p=px(path[i]),hop=Math.sin(t*Math.PI*Math.max(1,path.length-1))*(i===path.length-1?0:8);frames.push({offset:Math.max(0,Math.min(1,t)),transform:`translate(calc(-50% + ${p.x.toFixed(2)}px),calc(-43% + ${(p.y-hop).toFixed(2)}px)) scale(${i===path.length-1?1:.96})`,filter:i===path.length-1?'brightness(1)':'brightness(1.12)'})}frames[0].offset=0;frames[frames.length-1].offset=1;el.animate(frames,{duration:Math.max(320,Math.min(1150,220+path.length*88)),easing:'cubic-bezier(.22,.8,.24,1)',fill:'none'});session.lastMarbleAnimation=null}

