function trailPawnLayout(s,e){const len=e.trackLength||60,viewerStart=trailStartIndex(s,e,s.viewerId),all=[];for(const p of s.players){const start=trailStartIndex(s,e,p.id),sp=trailTrackPoint(start,viewerStart,len),arr=e.pawns?.[p.id]||[];arr.forEach((q,i)=>{let x,y,key;if(q.zone==='track'){const abs=(start+(q.dist||0))%len,pt=trailTrackPoint(abs,viewerStart,len);x=pt.x;y=pt.y;key=`t-${abs}`}else if(q.zone==='home'){const pt=trailSafePoint(sp,q.home);x=pt.x;y=pt.y;key=`h-${p.id}-${q.home}`}else{const dx=[-2.2,2.2,-2.2,2.2][i%4],dy=[-2,-2,2,2][i%4],f=1.075;x=50+(sp.x-50)*f+dx;y=50+(sp.y-50)*f+dy;key=`c-${p.id}-${i}`}all.push({p,q,i,x,y,key,start})})}const groups={};for(const item of all)(groups[item.key]??=[]).push(item);for(const g of Object.values(groups))if(g.length>1)g.forEach((item,i)=>{const a=i*2*Math.PI/g.length;item.x+=Math.cos(a)*1.5;item.y+=Math.sin(a)*1.5});return{items:all,viewerStart}}
